(()=>{'use strict';
 const days=[['ش',6,'شنبه'],['ی',0,'یکشنبه'],['د',1,'دوشنبه'],['س',2,'سه‌شنبه'],['چ',3,'چهارشنبه'],['پ',4,'پنجشنبه'],['ج',5,'جمعه']];
 const $=s=>document.querySelector(s), clean=v=>String(v||'').trim(), clock=v=>String(v||'').slice(0,5);
 const current=()=>typeof session!=='undefined'&&session?.user&&typeof mine==='function'&&mine()?session.user:null;
 const dayText=r=>days.filter(([,v])=>(r.weekdays||[]).map(Number).includes(v)).map(([, ,n])=>n).join('، ');
 async function list(){const user=current();if(!user)throw Error('برای تنظیم کار روتین وارد شوید.');const {data,error}=await db.from('sm_routine_alarms').select('*').eq('user_id',user.id).order('remind_at');if(error)throw error;return data||[]}
 function home(){return modalHead('کارهای روتین من')+'<section class="routine-reminders"><p class="routine-intro">یک قالب کار بسازید. در ساعت و روزهای انتخابی، همان کار به‌صورت خودکار در «کارهای من» ایجاد می‌شود تا انجامش را ثبت کنید.</p><div class="routine-toolbar"><button class="primary" type="button" id="routineAdd">＋ کار روتین جدید</button><small>اعلان این دستگاه را از بخش «اعلان‌های این دستگاه» فعال کنید.</small></div><div id="routineList" class="routine-list" aria-live="polite"></div></section>'}
 function form(r={active:true,weekdays:[6,0,1,2,3,4,5],remind_at:'08:00'}){const chosen=(r.weekdays||[]).map(Number);return `<section class="routine-editor"><button type="button" class="routine-back" id="routineBack">← بازگشت به کارهای روتین</button><h3>${r.id?'ویرایش کار روتین':'کار روتین جدید'}</h3><form id="routineForm"><label>عنوان کار<input name="title" maxlength="160" required placeholder="مثلاً ثبت گزارش روزانه" value="${esc(r.title||'')}"></label><label>شرح کار <small>(اختیاری)</small><textarea name="note" maxlength="800" rows="4" placeholder="شرحی که همراه هر کار جدید ثبت می‌شود">${esc(r.note||'')}</textarea></label><div class="routine-time-row"><label>ساعت ایجاد کار<input name="remind_at" type="time" required value="${clock(r.remind_at)||'08:00'}"></label><label class="routine-active"><input name="active" type="checkbox" ${r.active!==false?'checked':''}><span>روتین فعال باشد</span></label></div><fieldset><legend>روزهای تکرار</legend><div class="routine-day-picker">${days.map(([s,v,n])=>`<label title="${n}"><input type="checkbox" name="weekdays" value="${v}" ${chosen.includes(v)?'checked':''}><span>${s}</span></label>`).join('')}</div></fieldset><div class="routine-form-actions">${r.id?'<button class="danger" type="button" id="routineDelete">حذف روتین</button>':''}<button class="primary" type="submit">ذخیره روتین</button></div></form></section>`}
 async function renderList(){const box=$('#routineList');if(!box)return;box.innerHTML='<div class="routine-loading">در حال دریافت کارهای روتین…</div>';try{const rows=await list();box.innerHTML=rows.length?rows.map(r=>`<article class="routine-item ${r.active?'':'is-off'}"><button class="routine-toggle" type="button" data-toggle="${r.id}" aria-pressed="${r.active}">${r.active?'فعال':'خاموش'}</button><button class="routine-main" type="button" data-edit="${r.id}"><strong>${esc(r.title)}</strong>${r.note?`<small>${esc(r.note)}</small>`:''}<span>${clock(r.remind_at)} · ${dayText(r)} · ایجاد در کارهای من</span></button></article>`).join(''):'<div class="routine-empty"><b>هنوز کار روتینی ندارید.</b><span>برای کارهای تکراری، یک قالب بسازید تا در روز و ساعت دلخواه وارد فهرست کارهای شما شود.</span></div>';box.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.edit)));box.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{const r=rows.find(x=>x.id===b.dataset.toggle);b.disabled=true;const {error}=await db.from('sm_routine_alarms').update({active:!r.active,updated_at:new Date().toISOString()}).eq('id',r.id);if(error)message('تغییر ذخیره نشد.');await renderList()})}catch{box.innerHTML='<div class="routine-empty">دریافت کارهای روتین ممکن نشد. دوباره تلاش کنید.</div>'}}
 function edit(row={active:true,weekdays:[6,0,1,2,3,4,5],remind_at:'08:00'}){$('#sharedDetail').innerHTML=modalHead(row.id?'ویرایش کار روتین':'کار روتین جدید')+form(row);$('#sharedClose').onclick=()=>$('#sharedDialog').close();$('#routineBack').onclick=open;const f=$('#routineForm');f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type="submit"]'),v=new FormData(f),weekdays=[...f.querySelectorAll('[name="weekdays"]:checked')].map(x=>Number(x.value));if(!weekdays.length)return message('حداقل یک روز را انتخاب کنید.');if(!project?.id)return message('ابتدا پروژه را انتخاب کنید.');button.disabled=true;const payload={user_id:current().id,project_id:project.id,title:clean(v.get('title')),note:clean(v.get('note')),remind_at:v.get('remind_at'),weekdays,active:f.active.checked,updated_at:new Date().toISOString()};if(row.id)payload.id=row.id;const {error}=await db.from('sm_routine_alarms').upsert(payload);if(error){message('ذخیره روتین انجام نشد.');button.disabled=false;return}message('کار روتین ذخیره شد.');open()};const del=$('#routineDelete');if(del)del.onclick=async()=>{if(!confirm('این کار روتین حذف شود؟'))return;del.disabled=true;const {error}=await db.from('sm_routine_alarms').delete().eq('id',row.id);if(error){message('حذف انجام نشد.');del.disabled=false;return}message('روتین حذف شد.');open()}}
 function open(){if(!current())return message('اول وارد حساب خودتان شوید.');modal(home());$('#routineAdd').onclick=()=>edit();renderList()}
 function menu(){const panel=$('#accountMorePanel');if(!panel||$('#routineMenuButton'))return;const b=document.createElement('button');b.type='button';b.id='routineMenuButton';b.className='account-settings-link routine-menu-link';b.textContent='کارهای روتین من';b.onclick=()=>{panel.hidden=true;open()};panel.insertBefore(b,panel.querySelector('.account-trash-link')||null)}
 new MutationObserver(menu).observe(document.body,{childList:true,subtree:true});menu();window.SamandisOpenRoutines=open;if(new URL(location.href).searchParams.get('routine'))setTimeout(open,600);
})();
